            it = iter(j for j in xrange(start, len(nums), 2))
            return sum(abs(next(it)-i) for i in xrange(len(nums)) if nums[i]%2)

        cnt = sum(x%2 for x in nums)
        if cnt == len(nums)-cnt:
            return min(count(0), count(1))
