        """
        :type nums: List[int]
        :rtype: int
        """
        result = curr = 0
        for i, x in enumerate(nums):
            if i%2 == 0:
                while SPF[x] != x:
                    x += 1
                    result += 1
            else:
                while SPF[x] == x:
                    x += 1
                    result += 1
        return result


